@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#f1f1e8;--muted:#9ba9a4;--orange:#f1a24a;--blue:#6cb9ea;--panel:rgba(16,26,28,.94);--line:rgba(232,240,222,.12)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#182225;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none}.game-shell{position:relative;width:100%;height:100%;min-height:100svh;overflow:hidden;background:radial-gradient(ellipse at 50% 46%,#50634d 0%,#263b37 56%,#192627 100%);isolation:isolate}#battlefield{position:absolute;inset:0;width:100%;height:100%;display:block}.game-shell:after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,15,17,.62),transparent 25%,transparent 61%,rgba(9,17,18,.64));z-index:1}.topbar,.mission-card,.map-label,.toast,.unit-panel,.command-bar,.hint,.victory-screen,.round-toast{position:absolute;z-index:2}.topbar{top:max(14px,env(safe-area-inset-top));left:18px;right:18px;display:flex;align-items:center;gap:12px;height:44px}.brand{display:flex;gap:10px;align-items:center;flex:1}.brand-mark{width:37px;height:37px;background:var(--orange);color:#182225;display:grid;place-items:center;font:900 15px 'Barlow Condensed',sans-serif;letter-spacing:-1px;clip-path:polygon(0 0,100% 0,100% 78%,78% 100%,0 100%)}.eyebrow{font:500 9px 'DM Mono',monospace;letter-spacing:1.55px;color:#aab7ac}.brand h1{margin:-1px 0 0;font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1.3px;line-height:1}.brand h1 span{color:var(--orange)}.turn-pill{height:34px;padding:0 10px;background:rgba(12,21,23,.82);border:1px solid var(--line);display:flex;align-items:center;gap:7px;font:500 9px 'DM Mono',monospace;letter-spacing:.6px}.turn-pill i,.ping{width:7px;height:7px;border-radius:50%;background:#7bd69b;box-shadow:0 0 9px #7bd69b}.turn-pill b{color:var(--orange);font-weight:500}.icon-btn{width:34px;height:34px;border:1px solid var(--line);background:rgba(12,21,23,.82);color:var(--ink);font-size:16px;border-radius:3px}.mission-card{top:calc(max(14px,env(safe-area-inset-top)) + 58px);left:18px;width:min(330px,calc(100% - 36px));padding:12px 14px 10px;background:linear-gradient(110deg,rgba(13,23,24,.94),rgba(22,34,32,.88));border:1px solid rgba(226,232,210,.16);box-shadow:0 8px 26px #0e171755;clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%)}.mission-heading{display:flex;align-items:center;gap:9px}.mission-icon{font-size:21px;color:var(--orange)}.mission-heading strong{font-size:12px;letter-spacing:.1px}.timer{margin-left:auto;color:#f5c27e;font:500 10px 'DM Mono',monospace}.timer span{font-size:15px;margin-right:3px}.mission-progress{display:flex;align-items:center;gap:9px;margin:11px 0 9px;font:500 10px 'DM Mono',monospace;color:#dfe4d8}.progress-track{height:4px;flex:1;background:#ffffff1a}.progress-track i{height:100%;width:0;display:block;background:var(--orange);transition:width .35s}.objective-tags{display:flex;gap:14px;color:#b8c2b9;font:500 8px 'DM Mono',monospace;letter-spacing:.5px}.objective-tags span{display:flex;align-items:center;gap:5px}.blue-dot,.red-dot{width:6px;height:6px;border-radius:50%;display:inline-block;background:var(--blue)}.red-dot{background:#ee725f}.map-label{top:calc(max(14px,env(safe-area-inset-top)) + 175px);left:19px;color:#dce1d4;font:500 9px 'DM Mono',monospace;letter-spacing:1.2px;text-shadow:0 2px 6px #000}.map-label small{color:#92a49b;font-size:8px}.ping{display:inline-block;width:6px;height:6px;margin-right:7px}.toast{top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(12,20,20,.78);border:1px solid #ffffff24;border-radius:2px;padding:8px 12px;font:500 9px 'DM Mono',monospace;color:#e5e8dc;letter-spacing:.6px;white-space:nowrap;transition:opacity .4s;pointer-events:none}.toast.fade{opacity:0}.unit-panel{left:18px;bottom:calc(max(98px,env(safe-area-inset-bottom) + 82px));width:min(270px,calc(100% - 36px));min-height:56px;padding:8px 10px;display:flex;align-items:center;gap:9px;background:var(--panel);border:1px solid rgba(108,185,234,.32);box-shadow:0 8px 22px #09121266;transition:opacity .2s,transform .2s}.unit-panel.empty{opacity:0;transform:translateY(8px);pointer-events:none}.unit-avatar{height:35px;width:35px;display:grid;place-items:center;background:linear-gradient(145deg,#305772,#1b3440);border:1px solid #6cb9ea6b;color:#9bd8f8;font-size:22px}.unit-info{display:flex;flex-direction:column;gap:4px;min-width:105px}.unit-info strong{font-size:11px}.unit-info span,.unit-health span{font:500 8px 'DM Mono',monospace;color:#9eada9;letter-spacing:.5px}.unit-health{margin-left:auto;display:flex;flex-direction:column;gap:5px;width:70px}.unit-health div{height:4px;background:#ffffff1b}.unit-health i{display:block;width:100%;height:100%;background:#7bd69b;transition:width .2s}.command-bar{left:18px;right:18px;bottom:max(15px,env(safe-area-inset-bottom));display:flex;gap:7px;align-items:stretch;height:62px;padding:6px;background:rgba(13,22,23,.95);border:1px solid rgba(231,236,218,.13);box-shadow:0 9px 28px #080f11a3}.command-btn{flex:1;min-width:0;background:#ffffff08;border:1px solid transparent;color:#ccd4cb;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;border-radius:2px}.command-btn span{font-size:19px;line-height:21px}.command-btn small{font:600 8px 'DM Mono',monospace;letter-spacing:.4px}.command-btn.active{background:#e99a3f22;border-color:#e99a3f80;color:#ffc477}.command-btn:disabled{opacity:.35}.end-turn{flex:1.22;border:0;background:var(--orange);color:#172124;display:flex;align-items:center;justify-content:space-between;padding:0 12px;font:800 10px 'Barlow Condensed',sans-serif;letter-spacing:1px}.end-turn b{font-size:17px}.hint{left:50%;bottom:89px;transform:translateX(-50%);white-space:nowrap;color:#e5e8d6;font:500 8px 'DM Mono',monospace;letter-spacing:.85px;text-shadow:0 1px 5px #000}.hint span{color:var(--orange);padding:0 5px}.victory-screen{inset:0;display:grid;place-items:center;background:#091112bb;backdrop-filter:blur(5px);z-index:5}.victory-screen[hidden]{display:none}.result-card{width:min(380px,calc(100% - 36px));padding:30px 26px 26px;background:#172527;border:1px solid #f1a24a66;text-align:center;box-shadow:0 20px 70px #0009}.result-stamp{display:inline-block;color:var(--orange);border:1px solid #f1a24a88;padding:6px 9px;font:600 9px 'DM Mono',monospace;letter-spacing:1.4px;margin-bottom:16px}.result-card h2{font:800 32px 'Barlow Condensed',sans-serif;margin:8px 0}.result-card p{color:#b4c0b9;font-size:12px;line-height:1.6}.result-card button{margin-top:16px;padding:13px 20px;border:0;background:var(--orange);color:#182225;font:800 11px 'Barlow Condensed',sans-serif;letter-spacing:1px}.result-card button span{font-size:16px;margin-left:12px}.round-toast{top:50%;left:50%;transform:translate(-50%,-50%) scale(.96);background:#121e20ed;border:1px solid #f1a24a80;padding:15px 20px;color:#f8bf73;font:600 11px 'DM Mono',monospace;letter-spacing:1px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s}.round-toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}
@media (min-width:700px){.topbar{left:28px;right:28px}.mission-card{left:28px;top:82px}.map-label{left:30px;top:250px}.command-bar{left:28px;right:28px;width:500px;left:50%;transform:translateX(-50%);height:68px}.unit-panel{left:28px;bottom:100px}.hint{bottom:91px}.mission-card{width:350px}.unit-panel{width:285px}}
@media (max-height:650px){.mission-card{top:62px;padding:8px 12px}.mission-progress{margin:7px 0}.objective-tags{display:none}.map-label{top:152px}.command-bar{height:54px}.unit-panel{bottom:76px}.hint{bottom:72px}}

(() => {
  'use strict';
  const canvas = document.getElementById('battlefield'), ctx = canvas.getContext('2d');
  const W = 10, H = 12, names = ['Ranger squad', 'Recon team', 'Support team'];
  const units = [
    {id:'rangers',name:names[0],team:'blue',x:2,y:9,hp:4,max:4,ap:2,damage:2,range:4,kind:'rifle'},
    {id:'recon',name:names[1],team:'blue',x:1,y:10,hp:3,max:3,ap:2,damage:1,range:5,kind:'scout'},
    {id:'support',name:names[2],team:'blue',x:3,y:10,hp:4,max:4,ap:2,damage:2,range:4,kind:'heavy'},
    {id:'raiders',name:'Raider patrol',team:'red',x:7,y:3,hp:3,max:3,ap:0,damage:1,range:3,kind:'enemy'},
    {id:'guards',name:'Outpost guards',team:'red',x:6,y:5,hp:4,max:4,ap:0,damage:1,range:3,kind:'enemy'},
    {id:'scouts',name:'Scout patrol',team:'red',x:8,y:8,hp:3,max:3,ap:0,damage:1,range:3,kind:'enemy'}
  ];
  const sites = [
    {id:'west',name:'WEST DEPOT',x:2,y:5,progress:0,owner:'neutral'},
    {id:'ridge',name:'RIDGE COMMS',x:5,y:2,progress:0,owner:'neutral'},
    {id:'east',name:'EAST FUEL',x:7,y:7,progress:0,owner:'neutral'}
  ];
  const obstacles = [{x:4,y:3,type:'rock'},{x:4,y:4,type:'rock'},{x:7,y:5,type:'bunker'},{x:5,y:8,type:'tree'},{x:8,y:2,type:'tree'},{x:1,y:6,type:'tree'},{x:6,y:10,type:'rock'}];
  let selected = 'rangers', mode = 'select', turn = 1, timeLeft = 360, gameOver = false, busy = false, lastTick = 0, toastTimer = 0, shake = 0;
  let dpr=1, cw=0, ch=0, tw=44, th=25, scale=1, ox=0, oy=0;
  const el = id => document.getElementById(id), unit = id => units.find(u=>u.id===id), active = () => unit(selected), alive = u => u.hp>0;
  const dist = (a,b) => Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
  function tell(text){const t=el('toast');t.textContent=text;t.classList.remove('fade');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('fade'),2100)}
  function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=Math.round(cw*dpr);canvas.height=Math.round(ch*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min((cw-26)/((W+H)*44),(ch-205)/((W+H)*25),1.2);tw=44*scale;th=25*scale;ox=cw/2;oy=ch*.525;}
  function point(x,y){return {x:ox+(x-y)*tw/2,y:oy+((x+y)-(W+H-2)/2)*th/2}}
  function corners(x,y){const p=point(x,y);return [[p.x,p.y-th/2],[p.x+tw/2,p.y],[p.x,p.y+th/2],[p.x-tw/2,p.y]]}
  function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
  function hash(x,y){const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
  function terrain(x,y){const road=Math.abs(x-y*.53-1.6)<.52;const colors=['#617855','#667c58','#5d7453','#70845b','#5b704e'];let c=colors[Math.floor(hash(x,y)*colors.length)];if(road)c=['#897a5e','#8b7b60','#807358'][Math.floor(hash(y,x)*3)];return c}
  function drawTile(x,y){const c=corners(x,y),p=point(x,y);poly(c,terrain(x,y),'rgba(26,41,31,.19)');if(!((x+y)%3)){ctx.fillStyle='rgba(190,194,133,.18)';ctx.beginPath();ctx.ellipse(p.x+(hash(x,y)-.5)*tw*.35,p.y+(hash(y,x)-.5)*th*.24,1.25*scale,.7*scale,-.3,0,Math.PI*2);ctx.fill()}if((x*3+y*7)%11===2){ctx.strokeStyle='#a5a07944';ctx.lineWidth=scale;ctx.beginPath();ctx.moveTo(p.x-tw*.09,p.y+th*.1);ctx.lineTo(p.x+tw*.04,p.y-th*.1);ctx.stroke()}}
  function drawObjective(s){const p=point(s.x,s.y),r=13*scale;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#111b1db0';ctx.beginPath();ctx.ellipse(0,5*scale,17*scale,8*scale,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=s.owner==='blue'?'#77c8f1':s.progress?'#f1a24a':'#d7c58c';ctx.lineWidth=1.4*scale;ctx.setLineDash([3*scale,2*scale]);ctx.beginPath();ctx.ellipse(0,0,17*scale,8.5*scale,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
    if(s.owner==='blue'){ctx.fillStyle='#4480a0';ctx.fillRect(-6*scale,-9*scale,12*scale,10*scale);ctx.fillStyle='#9dd8ed';ctx.fillRect(-3*scale,-12*scale,6*scale,3*scale);ctx.fillStyle='#6cb9ea'}else{ctx.fillStyle='#807958';ctx.fillRect(-6*scale,-8*scale,12*scale,9*scale);ctx.fillStyle='#d2c49b';ctx.fillRect(-3*scale,-11*scale,6*scale,3*scale)}
    ctx.strokeStyle=s.owner==='blue'?'#92dbff':'#e8c879';ctx.lineWidth=1.5*scale;ctx.beginPath();ctx.moveTo(7*scale,-8*scale);ctx.lineTo(7*scale,-24*scale);ctx.stroke();ctx.fillStyle=s.owner==='blue'?'#65b9e8':s.progress?'#efa34d':'#d2bf81';ctx.beginPath();ctx.moveTo(8*scale,-24*scale);ctx.lineTo(17*scale,-21*scale);ctx.lineTo(8*scale,-18*scale);ctx.fill();ctx.font=`500 ${Math.max(7,8*scale)}px monospace`;ctx.textAlign='center';ctx.fillStyle='#f0eddd';ctx.shadowColor='#18201a';ctx.shadowBlur=4;ctx.fillText(s.name,0,-31*scale);ctx.restore()}
  function drawObstacle(o){const p=point(o.x,o.y);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#17211d55';ctx.beginPath();ctx.ellipse(0,4*scale,12*scale,6*scale,0,0,Math.PI*2);ctx.fill();if(o.type==='tree'){ctx.fillStyle='#504b36';ctx.fillRect(-2*scale,-11*scale,4*scale,12*scale);for(let i=0;i<3;i++){ctx.fillStyle=['#354b38','#405a3b','#4a6342'][i];ctx.beginPath();ctx.ellipse((i-1)*3*scale,-13*scale-i*3*scale,7*scale,7*scale,0,0,Math.PI*2);ctx.fill()}}else if(o.type==='rock'){poly([[-8*scale,-3*scale],[-6*scale,-10*scale],[1*scale,-13*scale],[8*scale,-7*scale],[8*scale,-2*scale]],'#777965','#4e5848')}else{ctx.fillStyle='#514c3b';ctx.fillRect(-10*scale,-10*scale,20*scale,10*scale);ctx.fillStyle='#77745c';ctx.fillRect(-12*scale,-12*scale,24*scale,4*scale);ctx.fillStyle='#2c3530';ctx.fillRect(-3*scale,-7*scale,6*scale,7*scale)}ctx.restore()}
  function drawUnit(u){if(!alive(u))return;const p=point(u.x,u.y),friend=u.team==='blue',sel=u.id===selected;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#10201d9c';ctx.beginPath();ctx.ellipse(0,4.5*scale,9.5*scale,5.4*scale,0,0,Math.PI*2);ctx.fill();if(sel){ctx.strokeStyle='#ffbd68';ctx.lineWidth=1.6*scale;ctx.beginPath();ctx.ellipse(0,2*scale,12*scale,7*scale,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffc777';ctx.beginPath();ctx.arc(0,-16*scale,2.2*scale,0,Math.PI*2);ctx.fill()}
    const color=friend?'#4b91b6':'#b65346',light=friend?'#79c4e7':'#e77864';ctx.strokeStyle='#202825';ctx.lineWidth=3.2*scale;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-2*scale,0);ctx.lineTo(-4*scale,4*scale);ctx.moveTo(2*scale,0);ctx.lineTo(4*scale,4*scale);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-1.5*scale,5.5*scale,7*scale,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=light;ctx.beginPath();ctx.arc(0,-8*scale,4.1*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle=friend?'#35483d':'#543d37';ctx.beginPath();ctx.arc(0,-9*scale,4.5*scale,Math.PI,Math.PI*2);ctx.fill();ctx.strokeStyle='#242c29';ctx.lineWidth=2*scale;ctx.beginPath();ctx.moveTo(4*scale,-2*scale);ctx.lineTo(10*scale,-7*scale);ctx.stroke();if(friend){ctx.fillStyle='#e7e4c9';ctx.fillRect(-1*scale,-9*scale,2*scale,1.5*scale)}
    const bw=14*scale;ctx.fillStyle='#101715bb';ctx.fillRect(-bw/2,-19*scale,bw,2.2*scale);ctx.fillStyle=u.hp/u.max>.5?'#84d49a':'#e6a14e';ctx.fillRect(-bw/2,-19*scale,bw*u.hp/u.max,2.2*scale);ctx.restore()}
  function drawRange(){const u=active();if(!u||!alive(u)||u.team!=='blue')return;if(mode==='move'){for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(dist(u,{x,y})<=3&&passable(x,y)){const c=corners(x,y);poly(c,'rgba(100,190,228,.14)','rgba(117,204,245,.25)')}}}if(mode==='attack'){ctx.strokeStyle='rgba(241,162,74,.32)';ctx.lineWidth=1;const p=point(u.x,u.y);ctx.beginPath();ctx.arc(p.x,p.y,tw*1.65,0,Math.PI*2);ctx.stroke()}}
  function passable(x,y){return x>=0&&y>=0&&x<W&&y<H&&!obstacles.some(o=>o.x===x&&o.y===y&&o.type!=='tree')}
  function render(){ctx.clearRect(0,0,cw,ch);const v=ctx.createRadialGradient(cw/2,ch*.5,20,cw/2,ch*.5,Math.max(cw,ch)*.65);v.addColorStop(0,'#78805c');v.addColorStop(.68,'#52664c');v.addColorStop(1,'#344942');ctx.fillStyle=v;ctx.fillRect(0,0,cw,ch);
    for(let s=0;s<W+H-1;s++)for(let x=0;x<W;x++){const y=s-x;if(y>=0&&y<H)drawTile(x,y)}
    drawRange();for(const o of obstacles.slice().sort((a,b)=>a.x+a.y-b.x-b.y))drawObstacle(o);for(const s of sites)drawObjective(s);for(const u of units.slice().sort((a,b)=>a.x+a.y-b.x-b.y))drawUnit(u);
    if(shake){shake*=.85;if(shake<.2)shake=0}requestAnimationFrame(render)}
  function updatePanel(){const u=active(),p=el('unitPanel');if(!u||!alive(u)||u.team!=='blue'){p.classList.add('empty');return}p.classList.remove('empty');el('unitName').textContent=u.name;el('unitDetail').textContent=`${u.hp} OPERATIVES · ${u.ap?'READY':'SPENT'}`;el('healthFill').style.width=`${100*u.hp/u.max}%`;el('healthFill').style.background=u.hp/u.max>.5?'#7bd69b':'#efa24a';document.querySelectorAll('.command-btn').forEach(b=>b.disabled=busy||!u.ap);document.querySelectorAll('.command-btn').forEach(b=>b.classList.remove('active'));if(mode==='move')el('moveBtn').classList.add('active');if(mode==='attack')el('attackBtn').classList.add('active');}
  function siteCount(){return sites.filter(s=>s.owner==='blue').length}
  function updateObjectives(){const n=siteCount();el('objectiveCount').textContent=`${n} / 3`;el('progressFill').style.width=`${n/3*100}%`;if(n===3)finish(true)}
  function finish(win){if(gameOver)return;gameOver=true;el('resultScreen').hidden=false;el('resultStamp').textContent=win?'MISSION COMPLETE':'SQUAD LOST';el('resultTitle').textContent=win?'Supply line secured.':'The ridge has fallen.';el('resultCopy').textContent=win?'Bravo Ridge is back in friendly hands. Your squad has changed the course of the campaign.':'Your forces have been overwhelmed. Regroup and try a different approach.';el('hint').style.display='none'}
  function consume(u){u.ap=Math.max(0,u.ap-1);updatePanel()}
  function attack(a,b){if(!a||!b||!alive(a)||!alive(b))return;if(dist(a,b)>a.range){tell('TARGET OUT OF RANGE');return}if(a.ap<1){tell('SQUAD HAS NO ACTIONS LEFT');return}consume(a);b.hp=Math.max(0,b.hp-a.damage);shake=5;if(navigator.vibrate)navigator.vibrate(35);tell(`${a.team==='blue'?'HIT CONFIRMED':'UNDER FIRE'} · ${b.hp?`${b.hp} STRENGTH LEFT`:'UNIT ELIMINATED'}`);if(b.hp===0&&b.team==='blue'&&units.filter(u=>u.team==='blue'&&alive(u)).length===0)finish(false);updatePanel()}
  function moveTo(u,x,y){if(!u||u.ap<1||!passable(x,y)){tell('POSITION BLOCKED');return}if(dist(u,{x,y})>3){tell('OUTSIDE MOVEMENT RANGE');return}if(units.some(v=>v!==u&&alive(v)&&v.x===x&&v.y===y)){tell('POSITION OCCUPIED');return}u.x=x;u.y=y;consume(u);tell(`${u.name.toUpperCase()} MOVED`);for(const s of sites)if(dist(u,s)<=1.25&&s.owner!=='blue')tell('OBJECTIVE IN RANGE · CAPTURE AT END TURN')}
  function captureSelected(){const u=active();if(!u||u.ap<1){tell('SELECT A READY SQUAD');return}const s=sites.find(s=>dist(u,s)<=1.25&&s.owner!=='blue');if(!s){tell('MOVE A SQUAD ONTO AN OBJECTIVE');return}consume(u);s.owner='blue';s.progress=1;updateObjectives();tell(`${s.name} SECURED`)}
  function nearestTarget(u,team){return units.filter(v=>v.team===team&&alive(v)).sort((a,b)=>dist(u,a)-dist(u,b))[0]}
  function enemyPhase(){busy=true;mode='select';el('phaseLabel').textContent='HOSTILE RESPONSE';el('endTurnBtn').disabled=true;updatePanel();const enemies=units.filter(u=>u.team==='red'&&alive(u));for(const e of enemies){const t=nearestTarget(e,'blue');if(!t)break;if(dist(e,t)<=e.range){t.hp=Math.max(0,t.hp-e.damage);tell(`HOSTILE FIRE · ${t.name.toUpperCase()} HIT`)}else{let opts=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const x=e.x+dx,y=e.y+dy;if(passable(x,y)&&Math.abs(dx)+Math.abs(dy)<=1&&!units.some(v=>v!==e&&alive(v)&&v.x===x&&v.y===y))opts.push({x,y})}opts.sort((a,b)=>dist(a,t)-dist(b,t));if(opts.length){e.x=opts[0].x;e.y=opts[0].y;if(dist(e,t)<=e.range)t.hp=Math.max(0,t.hp-e.damage)}}}
    for(const s of sites){if(s.owner==='blue')continue;const friend=units.some(u=>u.team==='blue'&&alive(u)&&dist(u,s)<=1),foe=units.some(u=>u.team==='red'&&alive(u)&&dist(u,s)<=1);if(friend&&!foe){s.progress++;if(s.progress>=1){s.owner='blue';tell(`${s.name} SECURED`)}}else if(foe)s.progress=0}
    if(units.filter(u=>u.team==='blue'&&alive(u)).length===0){busy=false;finish(false);return}updateObjectives();if(gameOver)return;turn++;for(const u of units)if(u.team==='blue'&&alive(u))u.ap=2;el('turnLabel').textContent=`DAY ${String(turn).padStart(2,'0')}`;el('phaseLabel').textContent='YOUR OPERATION';el('endTurnBtn').disabled=false;busy=false;updatePanel();const rt=el('roundToast');rt.textContent=`DAY ${String(turn).padStart(2,'0')} · ORDERS RECEIVED`;rt.classList.add('show');setTimeout(()=>rt.classList.remove('show'),1050);if(turn>8&&siteCount()<3)finish(false)}
  function endTurn(){if(gameOver||busy)return;enemyPhase()}
  function handleAt(px,py){if(gameOver||busy)return;const x=(px-ox)/tw+(py-oy)/th+(W+H-2)/2,y=-(px-ox)/tw+(py-oy)/th+(W+H-2)/2;const tx=Math.round(x),ty=Math.round(y);const hit=units.filter(u=>alive(u)).sort((a,b)=>dist({x:px,y:py},point(a.x,a.y))-dist({x:px,y:py},point(b.x,b.y)))[0];if(hit){const hp=point(hit.x,hit.y),rad=Math.max(18,tw*.47);if(Math.hypot(px-hp.x,py-hp.y)<rad){if(hit.team==='red'){const u=active();if(mode==='attack'&&u)attack(u,hit);else if(u&&dist(u,hit)<=u.range&&u.ap)attack(u,hit);else{selected=hit.id;updatePanel();tell(`${hit.name.toUpperCase()} · HOSTILE`)}return}selected=hit.id;mode='select';updatePanel();return}}
    const u=active();if(!u||u.team!=='blue')return;if(mode==='attack'){const foe=units.filter(v=>v.team==='red'&&alive(v)).sort((a,b)=>Math.abs(a.x-tx)+Math.abs(a.y-ty)-Math.abs(b.x-tx)-Math.abs(b.y-ty))[0];if(foe&&dist(foe,{x:tx,y:ty})<=1)attack(u,foe);else tell('TAP A HOSTILE UNIT');mode='select';updatePanel();return}if(mode==='move'||mode==='select'){if(tx>=0&&ty>=0&&tx<W&&ty<H)moveTo(u,tx,ty);mode='select';updatePanel()}}
  let pointerStart=null;canvas.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(pointerStart&&Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)<12)handleAt(e.clientX,e.clientY);pointerStart=null});
  el('moveBtn').onclick=()=>{mode=mode==='move'?'select':'move';updatePanel();tell(mode==='move'?'CHOOSE A CLEAR TILE':'ORDERS CLEARED')};el('attackBtn').onclick=()=>{mode=mode==='attack'?'select':'attack';updatePanel();tell(mode==='attack'?'SELECT A HOSTILE TARGET':'ORDERS CLEARED')};el('captureBtn').onclick=captureSelected;el('endTurnBtn').onclick=endTurn;
  el('restartBtn').onclick=()=>location.reload();let soundOn=true;el('soundBtn').onclick=()=>{soundOn=!soundOn;el('soundBtn').textContent=soundOn?'♫':'♪';tell(soundOn?'AUDIO ON':'AUDIO OFF')};
  setInterval(()=>{if(!gameOver&&!busy){timeLeft=Math.max(0,timeLeft-1);el('clock').textContent=`${String(Math.floor(timeLeft/60)).padStart(2,'0')}:${String(timeLeft%60).padStart(2,'0')}`;if(timeLeft===0)finish(false)}},1000);
  window.addEventListener('resize',resize);resize();updatePanel();tell('Tap a squad to issue orders');requestAnimationFrame(render);
